static pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;
static double tokens = BURST, rate = 100.0; static struct timespec last;
int allow(void) {                       /* 0 = refuse, 1 = admit */
    struct timespec now; clock_gettime(CLOCK_MONOTONIC, &now);
    pthread_mutex_lock(&m);
    double dt = (now.tv_sec - last.tv_sec) + (now.tv_nsec - last.tv_nsec) / 1e9;
    tokens = fmin(tokens + dt * rate, BURST); last = now;
    if (tokens < 1.0) { pthread_mutex_unlock(&m); return 0; }
    tokens -= 1.0;
    pthread_mutex_unlock(&m); return 1;
}
